    "ward.cover-setup-no-shifts": "ಸಿಬ್ಬಂದಿ ರೋಟರ್‌ನಲ್ಲಿ ಯಾವುದೇ ಶಿಫ್ಟ್‌ಗಳಿಲ್ಲ. Staff rota ನಲ್ಲಿ, ಪ್ರತಿ ವಾರ್ಡ್‌ಗೆ ಶಿಫ್ಟ್ ಅನ್ನು ವ್ಯಾಖ್ಯಾನಿಸಿ, ನಂತರ ನರ್ಸ್‌ಗಳು, ರೆಸಿಡೆಂಟ್‌ಗಳು ಮತ್ತು ಕನ್ಸಲ್ಟೆಂಟ್‌ಗಳನ್ನು ಅದಕ್ಕೆ ನಿಯೋಜಿಸಿ. ಅಲ್ಲಿಯವರೆಗೆ ನಿರ್ಣಾಯಕ ಫಲಿತಾಂಶದ ಹಂತ 2 ಅಲರ್ಟ್ ತಮ್ಮನ್ನು ಕರ್ತವ್ಯದಲ್ಲಿದ್ದಾರೆಂದು ಗುರುತಿಸಿಕೊಳ್ಳುವ ಜನರನ್ನು ಮಾತ್ರ ತಲುಪುತ್ತದೆ.",
