    "ward.qm-bed-utilisation-short": "ಬೆಡ್‌ಗಳ ಬಳಕೆ",
    "ward.qm-why-not-readable-with-role": "ಈ ರೋಲ್‌ನೊಂದಿಗೆ ಓದಲು ಸಾಧ್ಯವಿಲ್ಲ",
    "ward.qm-no-escalation-window": "ಈ ಆಸ್ಪತ್ರೆಯು ಯಾವುದೇ ಎಸ್ಕಲೇಶನ್ ವಿಂಡೋವನ್ನು ಕಾನ್ಫಿಗರ್ ಮಾಡಿಲ್ಲ, ಆದ್ದರಿಂದ ಅಳೆಯಲು ಯಾವುದೇ ಥ್ರೆಶೋಲ್ಡ್ ಇಲ್ಲ. ಸಂಸ್ಥೆಯಲ್ಲಿ wardsynq.criticalEscalation ಅನ್ನು ಸೆಟ್ ಮಾಡಿ.",
    "ward.qm-no-due-times": "ಈ ಅವಧಿಯಲ್ಲಿ ನೀಡಲಾದ {given} ಡೋಸ್‌ಗಳಲ್ಲಿ ಯಾವುದಕ್ಕೂ ನೀಡಬೇಕಾದ ಸಮಯವನ್ನು ನಮೂದಿಸಿಲ್ಲ, ಆದ್ದರಿಂದ ವಿಳಂಬವನ್ನು ಲೆಕ್ಕಹಾಕಲು ಸಾಧ್ಯವಿಲ್ಲ. 2026-09-07 ಕ್ಕಿಂತ ಮೊದಲು ಬರೆದ Administration ದಾಖಲೆಗಳು dueAt ಅನ್ನು ಹೊಂದಿರುವುದಿಲ್ಲ.",
    "ward.qm-no-allergy-status-record": "WardSynQ \"ವಿಚಾರಿಸಲಾಗಿದೆ, ಯಾವುದೇ ಅಲರ್ಜಿ ಇಲ್ಲ\" ಎಂದು ದಾಖಲಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ, ಆದ್ದರಿಂದ ಅಲರ್ಜಿ ದಾಖಲೆ ಇಲ್ಲದ ರೋಗಿಯನ್ನು ಯಾರೂ ವಿಚಾರಿಸದ ರೋಗಿಯಿಂದ ಬೇರ್ಪಡಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ. ಇಲ್ಲಿನ ಯಾವುದೇ ದರವು ಯಾರೂ ವಿಚಾರಿಸದ ವಾರ್ಡ್‌ಗೆ ಉತ್ತಮ ಡಾಕ್ಯುಮೆಂಟೇಶನ್ ಎಂದು ವರದಿ ಮಾಡುತ್ತದೆ. ಇದಕ್ಕೆ ಯಾವುದೇ ಅಲರ್ಜಿ ಇಲ್ಲ ಎಂಬ ದಾಖಲೆಯ ಅಗತ್ಯವಿದೆ, ಲೆಕ್ಕಾಚಾರದ್ದಲ್ಲ.",
    "ward.qm-type-unreadable": "{type} ದಾಖಲೆಗಳನ್ನು ಓದಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ: {why}",
    "ward.qm-records-unreadable": "ದಾಖಲೆಗಳನ್ನು ಓದಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ: {why}",
    "ward.qm-no-antibiotic-list": "Antibiotic ಪಟ್ಟಿಯನ್ನು ಕಾನ್ಫಿಗರ್ ಮಾಡಲಾಗಿಲ್ಲ. ಈ ಆಸ್ಪತ್ರೆಯು ಪರಿಗಣಿಸುವ ಡ್ರಗ್ ಹೆಸರುಗಳು ಅಥವಾ ಕೋಡ್‌ಗಳಿಗೆ ಸಂಸ್ಥೆಯಲ್ಲಿ wardsynq.antibiotics ಅನ್ನು ಸೆಟ್ ಮಾಡಿ.",
    "ward.qm-administrations-unreadable": "ಅಡ್ಮಿನಿಸ್ಟ್ರೇಷನ್ ಅಥವಾ ಎನ್‌ಕೌಂಟರ್ ರೆಕಾರ್ಡ್‌ಗಳನ್ನು ಓದಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ.",
    "ward.qm-reports-unreadable": "ವರದಿ ಅಥವಾ ವಿನಂತಿ ದಾಖಲೆಗಳನ್ನು ಓದಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ.",
    "ward.qm-no-beds-configured": "ಈ ಆಸ್ಪತ್ರೆಗೆ ಯಾವುದೇ ಹಾಸಿಗೆಗಳನ್ನು ಕಾನ್ಫಿಗರ್ ಮಾಡಲಾಗಿಲ್ಲ (wardsynq.beds), ಆದ್ದರಿಂದ ಲಭ್ಯವಿರುವ ಬೆಡ್-ಡೇಗಳ ಡೆನಾಮಿನೇಟರ್ ಇಲ್ಲ.",
    "ward.qm-too-few-cases-one": "ಈ ಅವಧಿಯಲ್ಲಿ {cases} ಪ್ರಕರಣ. ದರವೆಂದು ಓದಲು ತೀರಾ ಕಡಿಮೆ.",
    "ward.qm-too-few-cases": "ಈ ಅವಧಿಯಲ್ಲಿ {cases} ಪ್ರಕರಣಗಳು. ದರವೆಂದು ಓದಲು ತೀರಾ ಕಡಿಮೆ.",
    "ward.qm-no-bed-days": "ಈ ಅವಧಿಯಲ್ಲಿ ಆಕ್ರಮಿತ ಬೆಡ್-ಡೇಗಳಿಲ್ಲ, ಆದ್ದರಿಂದ ಯಾವುದೇ ದರವಿಲ್ಲ.",
    "ward.qm-below-minimum": "{denominator} ಅರ್ಹ ಪ್ರಕರಣಗಳು {minimum} ನ ಕನಿಷ್ಠ ಮಟ್ಟಕ್ಕಿಂತ ಕಡಿಮೆಯಿವೆ; ಇಲ್ಲಿನ ಶೇಕಡಾವಾರು ಪ್ರಮಾಣವನ್ನು ಅತ್ಯಂತ ದೊಡ್ಡ ಜನಸಂಖ್ಯೆಯ ಶೇಕಡಾವಾರುಗಳೊಂದಿಗೆ ಹೋಲಿಸಲಾಗುತ್ತದೆ ಮತ್ತು ಅವು ವಿಭಿನ್ನ ರೀತಿಯ ಸಂಖ್ಯೆಗಳೆಂದು ಯಾವುದೂ ಹೇಳುವುದಿಲ್ಲ",
    "ward.qm-beds-not-subtracted": "ಲಭ್ಯವಿರುವ ಹಾಸಿಗೆಗಳು ಕಾನ್ಫಿಗರ್ ಮಾಡಲಾದ ಹಾಸಿಗೆಗಳ ಪಟ್ಟಿಯಾಗಿದೆ; ಬ್ಲಾಕ್ ಮಾಡಿದ ಅಥವಾ ಮುಚ್ಚಿದ ಹಾಸಿಗೆಗಳನ್ನು ಕಳೆಯಲಾಗಿಲ್ಲ.",
    "ward.qm-deaths-source": "ಸಾವುಗಳನ್ನು ದಾಖಲಾದ ಮರಣದಿಂದ (Patient.deceased) ಅಥವಾ ಡಿಸ್ಚಾರ್ಜ್ ಡಿಸ್ಪೊಸಿಷನ್‌ನಿಂದ ಓದಲಾಗುತ್ತದೆ. ಎರಡೂ ಇಲ್ಲದ ತಂಗುವಿಕೆಯನ್ನು ಡೇಟಾ ಲಭ್ಯವಿಲ್ಲ ಎಂದು ಹೊರಗಿಡಲಾಗುತ್ತದೆ ಮತ್ತು ಎಣಿಸಲಾಗುತ್ತದೆ.",
    "ward.qm-readmissions-all-unplanned": "ದಾಖಲೆಯಲ್ಲಿ ಯಾವುದೇ ಪ್ಲಾನ್ಡ್-ರೀಅಡ್ಮಿಷನ್ ಫ್ಲ್ಯಾಗ್ ಇಲ್ಲ, ಆದ್ದರಿಂದ ಪ್ರತಿಯೊಂದು ರೀಅಡ್ಮಿಷನ್ ಅನ್ನು ಅನ್‌ಪ್ಲಾನ್ಡ್ ಎಂದು ಎಣಿಸಲಾಗುತ್ತದೆ.",
