    "site.admin.wards.bed.maintenance": "ನಿರ್ವಹಣೆಯಲ್ಲಿದೆ",
    "site.admin.staff.roleNote.admin": "ಸಂಪೂರ್ಣ ತಾಂತ್ರಿಕ ಆಡಳಿತ: ಸಿಬ್ಬಂದಿ, ವಾರ್ಡ್‌ಗಳು, ಬೆಡ್‌ಗಳು, ವಿಭಾಗಗಳು, ಕೊಠಡಿಗಳು, ಬಿಲ್ಲಿಂಗ್ ಕಾನ್ಫಿಗ್. ಕ್ಲಿನಿಕಲ್ ಪ್ರೋಟೋಕಾಲ್ ಸೈನ್-ಆಫ್ ಅಲ್ಲ.",
    "site.admin.staff.roleNote.doctor": "ಸಂಪೂರ್ಣ ಕ್ಲಿನಿಕಲ್ ಕಾರ್ಯಪ್ರವಾಹ: ಸರದಿ, EMR, ಆರ್ಡರ್‌ಗಳು, ಪ್ರಿಸ್ಕ್ರಿಪ್ಷನ್‌ಗಳು, ಸ್ವಂತ ರೋಗಿಗಳು.",
    "site.admin.staff.roleNote.nurse": "ಡೆಸ್ಕ್‌ನಲ್ಲಿ ಕ್ಯೂ ನಿರ್ವಹಿಸುತ್ತಾರೆ, ವೈಟಲ್ಸ್‌ಗಳನ್ನು ದಾಖಲಿಸುತ್ತಾರೆ, ಬೆಡ್‌ಸೈಡ್‌ನಲ್ಲಿ ಮದ್ದುಗಳನ್ನು ನೀಡುತ್ತಾರೆ (eMAR). ಪ್ರಿಸ್ಕ್ರಿಪ್ಷನ್ ಬರೆಯುವಂತಿಲ್ಲ.",
    "site.admin.staff.roleNote.reception": "ರೋಗಿಗಳನ್ನು ನೋಂದಾಯಿಸುತ್ತಾರೆ ಮತ್ತು ಚೆಕ್-ಇನ್ ಮಾಡುತ್ತಾರೆ, ವೈದ್ಯರಿಗೆ ನಿಯೋಜಿಸುತ್ತಾರೆ. ಚಾರ್ಟ್ ಓದಬಹುದು, ಎಡಿಟ್ ಮಾಡಲು ಸಾಧ್ಯವಿಲ್ಲ.",
    "site.admin.staff.roleNote.pharmacy": "ಔಷಧಿ ಆರ್ಡರ್‌ಗಳನ್ನು ಓದುತ್ತಾರೆ ಮತ್ತು ನೀಡುತ್ತಾರೆ, ಚಾರ್ಟ್ ವಿರುದ್ಧ ಆರ್ಡರ್ ಪರಿಶೀಲಿಸುತ್ತಾರೆ. ಕನ್ಸಲ್ಟೇಶನ್ ನೋಟ್‌ಗಳು ಇಲ್ಲ.",
    "site.admin.staff.roleNote.lab": "ಆರ್ಡರ್ ಮಾಡಿದ ಪರೀಕ್ಷೆಗಳನ್ನು ವೀಕ್ಷಿಸುತ್ತಾರೆ ಮತ್ತು ಫಲಿತಾಂಶಗಳನ್ನು ನೀಡುತ್ತಾರೆ. ಬೇರೆ ಯಾವುದೇ ಚಾರ್ಟ್ ಪ್ರವೇಶವಿಲ್ಲ.",
    "site.admin.staff.roleNote.billing": "ಚಾರ್ಜ್‌ಗಳು, ಇನ್‌ವಾಯ್ಸ್‌ಗಳು ಮತ್ತು ಕ್ಲೈಮ್‌ಗಳನ್ನು ಓದುತ್ತಾರೆ. ಪಾವತಿಯನ್ನು ಸ್ವೀಕರಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ (ಅದಕ್ಕಾಗಿ ಕ್ಯಾಷಿಯರ್ ನೋಡಿ).",
    "site.admin.staff.roleNote.him": "ಮಾಹಿತಿ ಬಿಡುಗಡೆ ವಿನಂತಿಗಳನ್ನು ನಿರ್ಧರಿಸಲು ಮತ್ತು ದಾಖಲಿಸಲು ಚಾರ್ಟ್ ಓದುತ್ತಾರೆ.",
    "site.admin.staff.roleNote.bloodBank": "ಕ್ರಾಸ್‌ಮ್ಯಾಚ್, ರಕ್ತ ನೀಡುವುದು ಮತ್ತು ಟ್ರಾನ್ಸ್‌ಫ್ಯೂಷನ್‌ಗಳನ್ನು ಮಾತ್ರ ನಿರ್ವಹಿಸುತ್ತದೆ.",
    "site.admin.staff.roleNote.radiographer": "ಇಮೇಜಿಂಗ್ ಅಧ್ಯಯನವನ್ನು ಪಡೆಯುತ್ತಾರೆ. ಚಾರ್ಟ್ ಓದಬಹುದು, ವರದಿ ಸಲ್ಲಿಸಲು ಅಥವಾ ಅಧ್ಯಯನವನ್ನು ಪ್ರೋಟೋಕಾಲ್ ಮಾಡಲು ಸಾಧ್ಯವಿಲ್ಲ.",
    "site.admin.staff.roleNote.radiologist": "ಇಮೇಜಿಂಗ್ ಅಧ್ಯಯನಗಳ ಪ್ರೋಟೋಕಾಲ್ ಮತ್ತು ವರದಿ ನೀಡುತ್ತಾರೆ (ಲ್ಯಾಬ್ ಫಲಿತಾಂಶ ಬಿಡುಗಡೆ ಬಳಸುವ ಅದೇ ಅಧಿಕಾರ). ಬೇರೆ ಯಾವುದೇ ಚಾರ್ಟ್ ರೈಟ್ ಇಲ್ಲ.",
