    "site.admin.hospital.noteWriters.title": "ಕ್ಲಿನಿಕಲ್ ನೋಟ್ ಅನ್ನು ಯಾರು ಬರೆಯಬಹುದು",
    "site.admin.hospital.noteWriters.intro": "ವೈದ್ಯರು ಮತ್ತು ಅಡ್ಮಿನ್‌ಗಳು ಯಾವಾಗಲೂ ನೋಟ್ ಬರೆಯಬಹುದು. ರೋಗಿಯ ಟೈಮ್‌ಲೈನ್‌ನಲ್ಲಿ ಡಾಕ್ಯುಮೆಂಟ್ ಮಾಡಲು ನಿಮ್ಮ ಆಸ್ಪತ್ರೆಯು ನಂಬುವ ಯಾವುದೇ ಇತರ ಪಾತ್ರವನ್ನು ಟಿಕ್ ಮಾಡಿ. ಇದು ಅವರಿಗೆ ನೋಟ್ ಬರೆಯಲು ಮಾತ್ರ ಅನುಮತಿಸುತ್ತದೆ ಮತ್ತು ಬೇರೇನೂ ಇಲ್ಲ: ಇದು ಅವರಿಗೆ ಪ್ರಿಸ್ಕ್ರೈಬ್ ಮಾಡಲು, ಆರ್ಡರ್ ಮಾಡಲು ಅಥವಾ ಯಾವುದನ್ನೂ ಬದಲಾಯಿಸಲು ಅನುಮತಿಸುವುದಿಲ್ಲ.",
    "site.admin.hospital.noteWriters.alwaysAllowed": "ಯಾವಾಗಲೂ ಅನುಮತಿಸಲಾಗಿದೆ: {roles}.",
