    "site.admin.hospital.printLang.toggle": "ರೋಗಿಯ ಪ್ರಿಸ್ಕ್ರಿಪ್ಷನ್ ಮತ್ತು ಡಿಸ್ಚಾರ್ಜ್ ಸಾರಾಂಶ ಪ್ರಿಂಟ್‌ಗಳಲ್ಲಿ ಎರಡನೇ ಭಾಷೆಯನ್ನು ನೀಡಿ",
    "site.admin.hospital.printLang.intro": "ಇಂಗ್ಲಿಷ್ ಪ್ರಿಂಟ್ ಯಾವಾಗಲೂ ಪೂರ್ಣವಾಗಿರುತ್ತದೆ ಮತ್ತು ಅಧಿಕೃತವಾಗಿರುತ್ತದೆ. ಎರಡನೇ ಭಾಷೆಯನ್ನು ಅದರ ಪಕ್ಕದಲ್ಲಿ ಮುದ್ರಿಸಲಾಗುತ್ತದೆ, ಅನುವಾದವೆಂದು ಗುರುತಿಸಲಾಗುತ್ತದೆ ಮತ್ತು ಶೀರ್ಷಿಕೆಗಳು, ಲೇಬಲ್‌ಗಳು ಹಾಗೂ ಸ್ಥಿರ ಪಟ್ಟಿಯಿಂದ ವೈದ್ಯರು ಆಯ್ಕೆ ಮಾಡಿದ ರೋಗಿಯ ಸೂಚನೆಗಳನ್ನು ಮಾತ್ರ ಒಳಗೊಂಡಿರುತ್ತದೆ. ಔಷಧಿ ಹೆಸರುಗಳು, ಡೋಸ್‌ಗಳು, ಆವರ್ತನಗಳು, ರೋಗನಿರ್ಣಯಗಳು, ಫಲಿತಾಂಶಗಳು ಮತ್ತು ಟೈಪ್ ಮಾಡಿದ ಯಾವುದನ್ನಾದರೂ ಇಂಗ್ಲಿಷ್‌ನಲ್ಲಿ ಮಾತ್ರ ಮುದ್ರಿಸಲಾಗುತ್ತದೆ. ಇನ್ನೂ ಬರೆಯದ ಅನುವಾದಗಳು ಇಂಗ್ಲಿಷ್‌ನಲ್ಲಿ ಕಾಣಿಸುತ್ತವೆ (ಇಲ್ಲ).",
