    "site.admin.hospital.alert.wardRuleNote": "ಲೆವೆಲ್ 2 ರಲ್ಲಿ, ಕೆಳಗಿನ ಕೋಷ್ಟಕದಲ್ಲಿರುವ \"ನರ್ಸ್\" ಈ ನಿಯಮವನ್ನು ಪ್ರತಿನಿಧಿಸುತ್ತದೆ. ನರ್ಸ್‌ಗಳು, ರೆಸಿಡೆಂಟ್‌ಗಳು ಮತ್ತು ಕನ್ಸಲ್ಟೆಂಟ್‌ಗಳು ವಾರ್ಡ್ ಸ್ಕ್ರೀನ್‌ನಲ್ಲಿ ತಮ್ಮನ್ನು ಆನ್ ಅಥವಾ ಆಫ್ ಡ್ಯೂಟಿ ಎಂದು ಗುರುತಿಸಿಕೊಳ್ಳುತ್ತಾರೆ; ಆಫ್ ಡ್ಯೂಟಿ ಅವರ ರೋಸ್ಟರ್ ಶಿಫ್ಟ್ ಮುಗಿಯುವವರೆಗೆ ಅಥವಾ 12 ಗಂಟೆಗಳ ಕಾಲ ಇರುತ್ತದೆ. ಈ ಕಾರ್ಡ್‌ನಲ್ಲಿ ನಿಯಮವನ್ನು ಬದಲಾಯಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ.",
    "site.admin.hospital.alert.noWardLead": "ಯಾವ ವಾರ್ಡ್ ದಾಖಲಾಗದ ರೋಗಿ: (ಇಲ್ಲ)",
    "site.admin.hospital.alert.noWardBody": "ಪ್ರತಿಯೊಂದು ಹಂತದಲ್ಲೂ, ಆ ವೈದ್ಯರು ತಮ್ಮನ್ನು ಆಫ್ ಡ್ಯೂಟಿ ಎಂದು ಗುರುತಿಸದ ಹೊರತು, ರೋಗಿಯನ್ನು ದಾಖಲಿಸಿಕೊಂಡ ವೈದ್ಯರಿಗೆ ಮತ್ತು ಆ ವೈದ್ಯರ ವಿಭಾಗದಲ್ಲಿ ಈಗ ಡ್ಯೂಟಿಯಲ್ಲಿರುವ ರೆಸಿಡೆಂಟ್‌ಗಳಿಗೆ ಅಲರ್ಟ್ ಹೋಗುತ್ತದೆ (ವಿಭಾಗ ತಿಳಿಯದಿದ್ದಾಗ ಆಸ್ಪತ್ರೆಯ ಎಲ್ಲಿಯಾದರೂ). ಡ್ಯೂಟಿಯಲ್ಲಿರುವ ಯಾವುದೇ ನರ್ಸ್, ಸೂಪರ್‌ವೈಸರ್ ಅಥವಾ ಇತರ ಕನ್ಸಲ್ಟೆಂಟ್‌ಗೆ ತಿಳಿಸಲಾಗುವುದಿಲ್ಲ. ಆರ್ಡರ್ ಮಾಡುವ ಕ್ಲಿನಿಷಿಯನ್ ಮತ್ತು ಹೆಸರಿಸಲಾದ ಸಂಪರ್ಕಗಳಿಗೆ ಇನ್ನೂ ಹೆಸರಿನ ಮೂಲಕ ತಿಳಿಸಲಾಗುತ್ತದೆ. ಅಡ್ಮಿಟ್ ಮಾಡುವ ವೈದ್ಯರು ಮತ್ತು ಡ್ಯೂಟಿಯಲ್ಲಿರುವ ರೆಸಿಡೆಂಟ್ ಇಲ್ಲದಿದ್ದರೆ, ಅಲರ್ಟ್ ಯಾರನ್ನೂ ತಲುಪಿಲ್ಲ ಎಂದು ದಾಖಲಾಗುತ್ತದೆ.",
    "site.admin.hospital.alert.phonesFailedLead": "ಯಾವ ಫೋನ್‌ಗಳು ನೋಂದಾಯಿಸಲ್ಪಟ್ಟಿವೆ ಎಂಬುದನ್ನು ಓದಲು ಸಾಧ್ಯವಾಗಿಲ್ಲ",
    "site.admin.hospital.alert.phonesFailedTrail": "ಎಲ್ಲರ ಬಳಿಯೂ ಒಂದಿದೆ ಎಂದು ಇದನ್ನು ಓದಬೇಡಿ.",
    "site.admin.hospital.alert.rotaPartial": "ರೋಟಾ ಪೂರ್ಣವಾಗಿ ಓದಲು ತುಂಬಾ ದೊಡ್ಡದಾಗಿತ್ತು, ಆದ್ದರಿಂದ ಕರ್ತವ್ಯದಲ್ಲಿರುವ ಕೆಲವು ವ್ಯಕ್ತಿಗಳು ಪಟ್ಟಿಯಲ್ಲಿಲ್ಲದಿರಬಹುದು.",
    "site.admin.hospital.alert.nobodyToCheck": "ಲ್ಯಾಡರ್‌ನಲ್ಲಿ ಪಾತ್ರವಿರುವ ಯಾರೂ ಈಗ ಡ್ಯೂಟಿಯಲ್ಲಿಲ್ಲ, ಮತ್ತು ಯಾವುದೇ ಸಂಪರ್ಕವನ್ನು ಹೆಸರಿಸಲಾಗಿಲ್ಲ, ಆದ್ದರಿಂದ ಪರಿಶೀಲಿಸಲು ಯಾರೂ ಇಲ್ಲ.",
    "site.admin.hospital.alert.allHavePhones": "ಲ್ಯಾಡರ್‌ನಲ್ಲಿ ಪಾತ್ರವನ್ನು ಹೊಂದಿರುವ ಡ್ಯೂಟಿಯಲ್ಲಿರುವ ಎಲ್ಲಾ {n} ಜನರು ಮತ್ತು ಹೆಸರಿಸಲಾದ ಸಂಪರ್ಕಗಳು ನೋಂದಾಯಿತ ಫೋನ್ ಹೊಂದಿದ್ದಾರೆ.",
