    "site.admin.security.ackArchiveNote": "ಈ ಸ್ವೀಕೃತಿಯ ಮೊದಲಿಗಿನ ಆಂಕರ್ ಲಾಗ್ ಅನ್ನು ಆರ್ಕೈವ್ ಆಗಿ ಇರಿಸಲಾಗುತ್ತದೆ ಮತ್ತು ಎಂದಿಗೂ ಅಳಿಸಲಾಗುವುದಿಲ್ಲ. ಈ ಹಂತದ ನಂತರದ ಹೊಸ ವ್ಯತ್ಯಾಸವನ್ನು ಮತ್ತೆ ವರದಿ ಮಾಡಲಾಗುತ್ತದೆ.",
    "site.admin.security.ackFormTitleOrg": "ಆಸ್ಪತ್ರೆಯ ಈವೆಂಟ್ ಲಾಗ್‌ನ ಕಾನೂನುಬದ್ಧ ಮರುಸ್ಥಾಪನೆಯನ್ನು ಸ್ವೀಕರಿಸಿ",
    "site.admin.security.ackFormTitle": "ಕಾನೂನುಬದ್ಧ ಮರುಸ್ಥಾಪನೆಯನ್ನು ಸ್ವೀಕರಿಸಿ",
    "site.admin.security.ackFormIntro": "ಇದು ಪ್ರಸ್ತುತ ಹೊರಗಿನ ಪ್ರತಿಯನ್ನು ಆರ್ಕೈವ್ ಮಾಡುತ್ತದೆ ಮತ್ತು ಅದನ್ನು ಹೊಸ ಸಾಲಿನಿಂದ ಮರುಪ್ರಾರಂಭಿಸುತ್ತದೆ ಮತ್ತು ನಿಮ್ಮ ಹೆಸರಿನಲ್ಲಿ ಆಡಿಟ್ ಟ್ರಯಲ್‌ನಲ್ಲಿ ಸ್ವೀಕೃತಿಯನ್ನು ದಾಖಲಿಸುತ್ತದೆ. ಮರುಸ್ಥಾಪನೆಯನ್ನು ಯೋಜಿಸಿದಾಗ ಮತ್ತು ಕೆಳಗಿನ ಇನ್ಸಿಡೆಂಟ್ ಉಲ್ಲೇಖದ ಅಡಿಯಲ್ಲಿ ಬರೆದಾಗ ಮಾತ್ರ ಇದನ್ನು ಮಾಡಿ. ಕಾರಣದಲ್ಲಿ ರೋಗಿಯ ವಿವರಗಳನ್ನು ಎಂದಿಗೂ ಹಾಕಬೇಡಿ.",
    "site.admin.security.whyRestored": "ಡೇಟಾಬೇಸ್ ಅನ್ನು ಏಕೆ ಮರುಸ್ಥಾಪಿಸಲಾಗಿದೆ (ಕನಿಷ್ಠ 20 ಅಕ್ಷರಗಳು)",
    "site.admin.security.whyRestoredPlaceholder": "ಯೋಜಿತ point in time restore ನಂತರ...",
