    "site.admin.security.back": "ಹಿಂದಕ್ಕೆ",
    "site.admin.security.integrityNoResult": "ಸತ್ಯಾಪಿಸಲಾಗಿಲ್ಲ: ಯಾವುದೇ ಸಮಗ್ರತೆಯ ಫಲಿತಾಂಶವು ಹಿಂತಿರುಗಿಲ್ಲ. ಇದು ಆಡಿಟ್ ಟ್ರಯಲ್ ಪೂರ್ಣವಾಗಿರುವುದಕ್ಕೆ ಸಮನಾಗಿಲ್ಲ.",
    "site.admin.security.chainedRow": "ಚೈನ್ಡ್ ರೌ",
