    "site.admin.security.found": "ಕಂಡುಬಂದಿದೆ",
    "site.admin.security.integrityNote": "ಪ್ರತಿಯೊಂದು ಆಡಿಟ್ ಸಾಲು ಹ್ಯಾಶ್ ಮೂಲಕ ಅದರ ಹಿಂದಿನ ಸಾಲಿಗೆ ಲಿಂಕ್ ಆಗಿರುತ್ತದೆ, ಆದ್ದರಿಂದ ಡೇಟಾಬೇಸ್‌ನಲ್ಲಿಯೇ ಮಾಡಲಾದ ಬದಲಾವಣೆ ಅಥವಾ ತೆಗೆದುಹಾಕುವಿಕೆ ಇಲ್ಲಿ ಕಾಣಿಸುತ್ತದೆ. ಹೊಸ ಸಾಲುಗಳನ್ನು ಪ್ರತಿ ಬಾರಿ ಪರಿಶೀಲಿಸಲಾಗುತ್ತದೆ. ಗಂಟೆಗೆೊಮ್ಮೆ ಹೊಸ ಸಾಲಿನ ಸಂಖ್ಯೆಯನ್ನು ಡೇಟಾಬೇಸ್‌ನ ಹೊರಗಿನ ಎರಡು ಸಂಗ್ರಹಣೆಗಳಿಗೆ (KV ಮತ್ತು Firestore) ನಕಲಿಸಲಾಗುತ್ತದೆ ಮತ್ತು ಇಲ್ಲಿ ಹೋಲಿಸಲಾಗುತ್ತದೆ, ಮತ್ತು ಎರಡು ಪ್ರತಿಗಳನ್ನು ಪರಸ್ಪರ ಹೋಲಿಸಲಾಗುತ್ತದೆ. ಇದನ್ನು ಆನ್ ಮಾಡುವ ಮೊದಲು ಬರೆದ ಸಾಲುಗಳು ಲಿಂಕ್ ಆಗಿರುವುದಿಲ್ಲ ಮತ್ತು ಪರಿಶೀಲಿಸಲು ಲಾರವು.",
