    "site.admin.export.title": "ಡೇಟಾ ರಫ್ತು (FHIR)",
    "site.admin.export.intro": "ಈ ಆಸ್ಪತ್ರೆಯ ದಾಖಲೆಯನ್ನು FHIR R4 NDJSON ಆಗಿ, ಹಿನ್ನೆಲೆಯಲ್ಲಿ ಪ್ರತಿಯೊಂದು ರಿಸೋರ್ಸ್ ಪ್ರಕಾರಕ್ಕೆ ಒಂದು ಫೈಲ್‌ನಂತೆ ರಫ್ತು ಮಾಡುತ್ತದೆ. ಒಂದು ಬಾರಿಗೆ ಒಂದು ರಫ್ತು ಮಾತ್ರ ಚಾಲನೆಯಾಗುತ್ತದೆ. ಈ ಆಸ್ಪತ್ರೆಯ ದೃಢೀಕರಣದೊಂದಿಗೆ ಫೈಲ್‌ಗಳನ್ನು ಇಲ್ಲಿ ಅಥವಾ FHIR ಬಲ್ಕ್ ಡೇಟಾ API ($export-status) ಮೂಲಕ ಡೌನ್‌ಲೋಡ್ ಮಾಡಲಾಗುತ್ತದೆ; ಪ್ರತಿಯೊಂದು ಡೌನ್‌ಲೋಡ್ ಅನ್ನು ಆಡಿಟ್ ಟ್ರಯಲ್‌ನಲ್ಲಿ ದಾಖಲಿಸಲಾಗುತ್ತದೆ ಮತ್ತು 24 ಗಂಟೆಗಳ ನಂತರ ಫೈಲ್‌ಗಳನ್ನು ಅಳಿಸಲಾಗುತ್ತದೆ.",
