    "site.admin.webhooks.intro2": "ಸ್ವೀಕರಿಸುವ ಸಿಸ್ಟಮ್ WardSynQ FHIR API ಮೂಲಕ ತನ್ನದೇ ಆದ SMART ಪ್ರವೇಶದೊಂದಿಗೆ ವಿವರಗಳನ್ನು ಓದುತ್ತದೆ, ಅಲ್ಲಿ ಈ ಆಸ್ಪತ್ರೆಯ ಅನುಮತಿಗಳು ಮತ್ತು ಆಡಿಟ್ ಟ್ರೇಲ್ ಅನ್ವಯಿಸುತ್ತವೆ.",
    "site.admin.webhooks.intro3": "ಪ್ರತಿಯೊಂದು ಕಾಲ್ ಅನ್ನೂ ಸೈನ್ ಮಾಡಲಾಗಿದೆ: X-WardSynQ-Signature ಎನ್ನುವುದು ಎಂಡ್‌ಪಾಯಿಂಟ್‌ನ ಸಿಪಾಯಿ/ಸೀಕ್ರೆಟ್‌ನೊಂದಿಗೆ X-WardSynQ-Timestamp, ಚುಕ್ಕೆ ಮತ್ತು ಬಾಡಿಯ HMAC-SHA256 ಆಗಿದೆ.",
