    "site.admin.smart.intro1": "FHIR ನಲ್ಲಿ SMART ಮೂಲಕ ತನ್ನ ದಾಖಲೆಯನ್ನು ಓದಲು ಈ ಆಸ್ಪತ್ರೆಯು ಅನುಮತಿಸುವ ಹೊರಗಿನ ಅಪ್ಲಿಕೇಶನ್‌ಗಳು: ಕ್ಲಿನಿಷಿಯನ್ ಬಳಸುವ ಅಪ್ಲಿಕೇಶನ್ (ಸಾರ್ವಜನಿಕ), ಅಥವಾ ಕೀಲಿಯೊಂದಿಗೆ ನೋಂದಾಯಿತ ಸಿಸ್ಟಮ್ (ಬ್ಯಾಕೆಂಡ್).",
    "site.admin.smart.intro2": "ನೋಂದಣಿಯು ಅನುಮತಿ ಪಟ್ಟಿಯಾಗಿದೆ: ಇಲ್ಲಿ ಹೆಸರಿಸದ ಅಪ್ಲಿಕೇಶನ್ ಏನನ್ನೂ ಪಡೆಯುವುದಿಲ್ಲ, ಮತ್ತು ಒಂದನ್ನು ತೆಗೆದುಹಾಕುವುದರಿಂದ ಅದರ ಟೋಕನ್‌ಗಳು ತಕ್ಷಣವೇ ನಿಲ್ಲುತ್ತವೆ. ಸ್ವಿಚ್ ಆಫ್ ಮಾಡುವುದರಿಂದ ಪ್ರತಿಯೊಂದು ಅಪ್ಲಿಕೇಶನ್‌ಗೆ SMART ಬಾಗಿಲು ಮುಚ್ಚುತ್ತದೆ.",
