    "site.maik.governedNote": "MaiK ದಾಖಲೆಯಿಂದ ಕರಡುಗಳನ್ನು ಸಿದ್ಧಪಡಿಸುತ್ತದೆ ಮತ್ತು ವೈದ್ಯರು ಸ್ವೀಕರಿಸುವವರೆಗೆ ಅದರ ಉತ್ತರಗಳು ಸಹಿ ಮಾಡಲ್ಪಡುವುದಿಲ್ಲ. ಪ್ರತಿಯೊಂದು ಸಂವಹನವನ್ನು ಅದರ ಮಾಡೆಲ್, ಮೂಲಗಳು ಮತ್ತು ನಿಮ್ಮ ಪರಿಶೀಲನೆಯೊಂದಿಗೆ ದಾಖಲೆಗೆ ಬರೆಯಲಾಗುತ್ತದೆ. ಈ ಬಿಲ್ಡ್‌ನಲ್ಲಿರುವ ಕ್ಲಿನಿಕಲ್ ವಿಷಯವನ್ನು ಆಸ್ಪತ್ರೆಯ ಸಮಿತಿಯು ಇನ್ನೂ ಸಹಿ ಮಾಡಿಲ್ಲ.",
